CREATE OR REPLACE VIEW redgate.feedback_audit_summary AS
SELECT audit_id, customer_id AS cust_id, created_at
FROM redgate.feedback_audit;

CREATE OR REPLACE FUNCTION redgate.count_recent_audits(p_days integer)
RETURNS integer
LANGUAGE plpgsql
AS $$
DECLARE v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM redgate.feedback_audit a
  WHERE a.created_at > now() - (p_days || ' days')::interval;
  RETURN v_count;
END$$;
